
const WORDS=[{"id": 0, "w": "过分", "p": "guòfèn", "t": "形容词", "m": "quá đáng, quá mức", "coll": "要求过分、过分强调", "s": "对孩子提出过分的要求，可能会给他们带来压力。"}, {"id": 1, "w": "强调", "p": "qiángdiào", "t": "动词", "m": "nhấn mạnh", "coll": "反复强调、强调重要性", "s": "老师反复强调，阅读以后还要认真思考。"}, {"id": 2, "w": "作文", "p": "zuòwén", "t": "名词", "m": "bài làm văn", "coll": "写作文、修改作文", "s": "写完作文以后，她又仔细修改了一遍。"}, {"id": 3, "w": "观点", "p": "guāndiǎn", "t": "名词", "m": "quan điểm", "coll": "表达观点、不同观点", "s": "讨论时，每个人都可以表达自己的观点。"}, {"id": 4, "w": "客观", "p": "kèguān", "t": "形容词", "m": "khách quan", "coll": "客观评价、客观事实", "s": "评价一部作品时，我们应该尽量保持客观。"}, {"id": 5, "w": "全面", "p": "quánmiàn", "t": "形容词", "m": "toàn diện, mọi mặt", "coll": "全面了解、全面分析", "s": "作决定之前，需要先全面了解情况。"}, {"id": 6, "w": "转变", "p": "zhuǎnbiàn", "t": "动词", "m": "thay đổi", "coll": "转变想法、转变学习方式", "s": "参加这次活动以后，他开始转变自己的学习方式。"}, {"id": 7, "w": "观念", "p": "guānniàn", "t": "名词", "m": "quan niệm, tư tưởng", "coll": "传统观念、改变观念", "s": "随着社会的发展，人们的观念也在不断变化。"}, {"id": 8, "w": "火柴", "p": "huǒchái", "t": "名词", "m": "diêm quẹt", "coll": "一根火柴、划火柴", "s": "他划了一根火柴，点亮了桌上的蜡烛。"}, {"id": 9, "w": "灰", "p": "huī", "t": "名词／形容词", "m": "tro; xám", "coll": "烧成灰、一堆灰", "s": "大火过后，那些旧报纸都变成了灰。"}, {"id": 10, "w": "一旦", "p": "yídàn", "t": "副词", "m": "một khi", "coll": "一旦发现、一旦决定", "s": "一旦发现问题，就应该及时解决。"}, {"id": 11, "w": "王宫", "p": "wánggōng", "t": "名词", "m": "hoàng cung", "coll": "参观王宫、古老的王宫", "s": "游客们正在参观一座古老的王宫。"}, {"id": 12, "w": "王子", "p": "wángzǐ", "t": "名词", "m": "hoàng tử", "coll": "勇敢的王子、王子和公主", "s": "这个童话讲的是一位勇敢的王子的故事。"}, {"id": 13, "w": "属于", "p": "shǔyú", "t": "动词", "m": "thuộc về", "coll": "属于自己、属于大家", "s": "这间活动室属于大家，请共同保持整洁。"}, {"id": 14, "w": "对待", "p": "duìdài", "t": "动词", "m": "đối xử", "coll": "认真对待、平等对待", "s": "不管任务大小，我们都应该认真对待。"}, {"id": 15, "w": "交换", "p": "jiāohuàn", "t": "动词", "m": "trao đổi", "coll": "交换意见、交换礼物", "s": "讨论结束后，两位老师交换了意见。"}, {"id": 16, "w": "拥有", "p": "yǒngyǒu", "t": "动词", "m": "có", "coll": "拥有机会、拥有经验", "s": "她拥有丰富的教学经验，很受学生欢迎。"}, {"id": 17, "w": "巨大", "p": "jùdà", "t": "形容词", "m": "to lớn", "coll": "巨大变化、巨大影响", "s": "网络的发展给人们的生活带来了巨大变化。"}, {"id": 18, "w": "承认", "p": "chéngrèn", "t": "动词", "m": "thừa nhận, chấp nhận", "coll": "承认错误、公开承认", "s": "他主动承认了错误，并向大家道歉。"}, {"id": 19, "w": "人性", "p": "rénxìng", "t": "名词", "m": "bản tính con người", "coll": "了解人性、人性的弱点", "s": "这部小说通过人物的选择，表现了人性的复杂。"}, {"id": 20, "w": "完美", "p": "wánměi", "t": "形容词", "m": "hoàn hảo, hoàn mỹ", "coll": "完美的计划、追求完美", "s": "这个方案虽然还不完美，但已经有了很大进步。"}, {"id": 21, "w": "难免", "p": "nánmiǎn", "t": "形容词", "m": "khó tránh", "coll": "难免出错、难免遇到困难", "s": "刚开始学习时，难免会遇到困难，不要轻易放弃。"}, {"id": 22, "w": "疼爱", "p": "téng'ài", "t": "动词", "m": "thương yêu", "coll": "疼爱孩子、十分疼爱", "s": "爷爷奶奶一直十分疼爱她。"}, {"id": 23, "w": "平等", "p": "píngděng", "t": "形容词", "m": "bình đẳng, công bằng", "coll": "平等交流、平等的机会", "s": "每个人都应该拥有平等的学习机会。"}, {"id": 24, "w": "自私", "p": "zìsī", "t": "形容词", "m": "ích kỷ", "coll": "自私的行为、不能太自私", "s": "只考虑自己而不顾别人，是一种自私的行为。"}, {"id": 25, "w": "倾向", "p": "qīngxiàng", "t": "动词／名词", "m": "nghiêng về; khuynh hướng", "coll": "倾向于、明显的倾向", "s": "比较了两个方案以后，我更倾向于选择第二个。"}, {"id": 26, "w": "理由", "p": "lǐyóu", "t": "名词", "m": "lý do", "coll": "说明理由、充分的理由", "s": "提出不同意见时，请说明你的理由。"}, {"id": 27, "w": "道德", "p": "dàodé", "t": "名词", "m": "đạo đức", "coll": "道德观念、社会道德", "s": "学校不仅要传授知识，还要重视道德教育。"}, {"id": 28, "w": "自从", "p": "zìcóng", "t": "介词", "m": "từ lúc", "coll": "自从那天起、自从毕业以后", "s": "自从参加读书会以后，她认识了不少新朋友。"}, {"id": 29, "w": "童话", "p": "tónghuà", "t": "名词", "m": "truyện hư cấu", "coll": "读童话、一本童话书", "s": "每天睡觉前，妈妈都会给孩子读一个童话。"}, {"id": 30, "w": "价值", "p": "jiàzhí", "t": "名词", "m": "giá trị", "coll": "具有价值、研究价值", "s": "这批资料具有很高的研究价值。"}, {"id": 31, "w": "单纯", "p": "dānchún", "t": "形容词", "m": "đơn thuần, đơn giản, chỉ", "coll": "想法单纯、单纯依靠", "s": "学习时，不能单纯依靠记忆，还要学会理解。"}, {"id": 32, "w": "主张", "p": "zhǔzhāng", "t": "动词／名词", "m": "cho là, tán thành; chủ trương", "coll": "主张改革、提出主张", "s": "他主张先调查，再提出解决问题的方案。"}, {"id": 33, "w": "知感", "p": "zhīgǎn", "t": "名词", "m": "tri giác", "coll": "知感与思考、停留在知感层面", "s": "学习不能只停留在知感层面，还需要深入思考。"}];
