'use strict';
const root=document.getElementById('ntc-design-preview');
const $=id=>document.getElementById(id);
const STORE='ngocthucac-hsk5-bai22-learning-v3';
const pages=['词汇表','学习生词','词汇卡片','综合练习','连词成句','学习统计'];
let storageOK=true,store={active:null,profiles:{}};
try{let raw=localStorage.getItem(STORE);if(raw){let parsed=JSON.parse(raw);if(parsed&&parsed.profiles)store=parsed}}catch(e){storageOK=false}
let student=store.active?store.profiles[store.active]:null;
if(!student){store.active='local';student=store.profiles.local||createStudent('','');store.profiles.local=student;}
let ui=student?.ui||{page:0,g:0,idx:0,pinyin:false};
let speed=1,playback=null,audioGeneration=0;
const group=g=>WORDS.slice(g*10,g===2?WORDS.length:g*10+10);
const groupOf=id=>Math.min(2,Math.floor(id/10));
const escapeHTML=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const hasLearned=id=>!!student?.studied.includes(id);
const learned=g=>group(g).filter(d=>hasLearned(d.id)).length;
const allLearned=()=>!!student&&student.studied.length===WORDS.length;
const memory=id=>student?.memory[id]||'new';
const weakIds=()=>WORDS.filter(d=>memory(d.id)==='review').map(d=>d.id);
const totalLearned=()=>student?.studied.length||0;
const currentWord=()=>group(ui.g)[ui.idx];
function shuffle(a){let b=[...a];for(let i=b.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[b[i],b[j]]=[b[j],b[i]]}return b}
function toast(message){let t=$('ntc-toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000)}
function save(){if(student){student.ui={...ui};student.updatedAt=new Date().toISOString()}try{localStorage.setItem(STORE,JSON.stringify(store))}catch(e){storageOK=false;toast('浏览器无法保存学习进度，请允许保存本地数据。')}}
function createStudent(name,clas){return {name,clas,studied:[],memory:{},bookmark:{g:0,idx:0},ui:{page:0,g:0,idx:0,pinyin:false},flash:null,quiz:null,order:null,quizHistory:[],orderHistory:[],timeMs:0}}
function status(id){if(!hasLearned(id))return '<span class="ntc-state new">○ 未学习</span>';if(memory(id)==='review')return '<span class="ntc-state review">↻ 需要复习</span>';return '<span class="ntc-state">✓ 已学习</span>'}
function button(label,action,cls='',disabled=false){return `<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${label}</button>`}
function go(page){stopAudio();ui.page=page;if(student&&allLearned()){if(page===2&&!student.flash)startFlash('all',false);if(page===3&&!student.quiz)startQuiz(false);if(page===4&&!student.order)startOrder(null,false)}save();render()}
function chooseGroup(g){stopAudio();ui.g=g;ui.idx=0;ui.page=1;save();render()}
function heading(title,subtitle='',tag=''){return `<div class="ntc-sectionhead"><div><h2>${title}</h2>${subtitle?`<p class="ntc-caption">${subtitle}</p>`:''}</div>${tag?`<span class="ntc-tag">${tag}</span>`:''}</div>`}
function meter(value,total){return `<div class="ntc-meter" role="progressbar" aria-label="进度" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${total}"><span style="width:${total?value/total*100:0}%"></span></div>`}
function gate(){return `<div class="ntc-panel ntc-lock"><div class="ntc-kicker">先学习生词，再进行全课复习</div><h2>请先完成生词学习</h2><p>已学习 ${totalLearned()}/34 个词语。学完三组词语后，即可进行词汇卡片、综合练习和连词成句。</p>${meter(totalLearned(),34)}<div class="ntc-progressgroups">${[0,1,2].map(g=>`<button data-group="${g}">组别 ${g+1}<br>${learned(g)}/${group(g).length}个词语</button>`).join('')}</div>${button('继续学习 →','resume','ntc-primary')}</div>`}
function listView(){return `<div class="ntc-panel">${heading('词汇表','全课共34个词语，点击 ↗ 学习该词语',totalLearned()+'/34 已学习')}<div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>汉字</th><th class="ntc-colpinyin">拼音</th><th class="ntc-coltype">词性</th><th>越南语释义</th><th>状态</th></tr></thead><tbody>${WORDS.map((d,i)=>`<tr><td class="ntc-hanzi">${d.w} <button class="ntc-play" data-word="${i}" aria-label="学习词语 ${d.w}">↗</button><button class="ntc-play" data-audio-word="${i}" aria-label="听词语 ${d.w}">◖</button></td><td class="ntc-colpinyin">${escapeHTML(d.p)}</td><td class="ntc-coltype">${escapeHTML(d.t)}</td><td>${escapeHTML(d.m)}</td><td>${status(i)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-actions"><span class="ntc-caption">仅生词学习分为三组：10、10、14个词语。</span>${button('开始／继续学习 →','resume','ntc-primary')}</div></div>`}
function studyView(){let d=currentWord(),a=group(ui.g),isLast=d.id===33;return `<div class="ntc-panel">${heading('学习生词 · 组别 '+(ui.g+1),'学习词语、搭配与例句',`${ui.idx+1}/${a.length}`)}${meter(learned(ui.g),a.length)}<div class="ntc-study"><div class="ntc-wordbox"><div class="ntc-pinyin" style="visibility:${ui.pinyin?'visible':'hidden'}">${escapeHTML(d.p)}</div><div class="ntc-bigword ntc-writing" id="ntc-writing" aria-label="汉字笔顺">${d.w}</div><div class="ntc-meaning">${escapeHTML(d.m)}</div><span class="ntc-type">${escapeHTML(d.t)}</span><div class="ntc-smallbtns">${button('笔顺演示','strokes')}<button data-audio-word="${d.id}">◖ 听词语</button>${button(ui.pinyin?'隐藏拼音':'显示拼音','pinyin')}</div></div><div><div class="ntc-label">常用搭配</div><div class="ntc-cn">${escapeHTML(d.coll)}</div><hr><div class="ntc-label">例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><div class="ntc-smallbtns"><button data-audio-example="${d.id}">◖ 听例句</button></div><div class="ntc-note">${status(d.id)}</div></div></div><div class="ntc-actions">${button('← 上一个','prev-study','',d.id===0)}${button(isLast?'✓ 已学习 · 全课复习 →':ui.idx===a.length-1?'✓ 已学习 · 下一组 →':'✓ 已学习 · 下一个 →','mark-study','ntc-primary')}</div><div class="ntc-footnote">点击“已学习”记录学习进度。需要时，可点击“笔顺演示”查看汉字的书写顺序。</div></div>`}
function markStudy(){let d=currentWord();if(!student.studied.includes(d.id))student.studied.push(d.id);let next=WORDS.find(x=>!student.studied.includes(x.id));if(d.id<33){let id=d.id+1;ui.g=groupOf(id);ui.idx=id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx}}else if(!next){ui.page=2;student.bookmark={g:2,idx:13};if(!student.flash)startFlash('all',false)}else{ui.g=groupOf(next.id);ui.idx=next.id-ui.g*10;student.bookmark={g:ui.g,idx:ui.idx};toast('还有未学完的词语，请继续学习。')}save();render()}
function startFlash(filter='all',redraw=true){let ids=filter==='weak'?weakIds():WORDS.map(d=>d.id);if(!ids.length){toast('暂无需要复习的词语。');return}student.flash={filter,ids:shuffle(ids),at:0,flipped:false,ratings:{},done:false};save();if(redraw)render()}
function flashView(){let f=student.flash;if(f.done)f.done=false;let d=WORDS[f.ids[f.at]];return `<div class="ntc-panel">${heading('词汇卡片 · 全课复习',f.filter==='weak'?'复习练习中答错的词语':'全课34个词语随机排列，不分组',`${f.at+1}/${f.ids.length}`)}${meter(f.at+1,f.ids.length)}<div class="ntc-smallbtns" style="margin-bottom:16px">${button('重新打乱全课34个词语','flash-all')}${button('待复习词语 ('+weakIds().length+')','flash-weak','',!weakIds().length)}</div><div class="ntc-flash"><span class="ntc-label">${f.flipped?'背面':'正面'}</span>${f.flipped?`<span class="ntc-pinyin">${escapeHTML(d.p)}</span><span class="ntc-meaning">${escapeHTML(d.m)}</span><span class="ntc-type">${escapeHTML(d.t)}</span><small>${escapeHTML(d.coll)}</small><div class="ntc-note"><span class="ntc-cn">${escapeHTML(d.s)}</span><button class="ntc-play" data-audio-example="${d.id}" aria-label="听例句">◖</button></div>`:`<div style="display:flex;align-items:center;justify-content:center;gap:12px"><span class="ntc-bigword" style="font-size:clamp(40px,${d.w.length>2?'7':'10'}vw,${d.w.length>2?'80':'112'}px)">${d.w}</span><button class="ntc-play" data-audio-word="${d.id}" aria-label="听发音 ${d.w}" title="听发音">🔊</button></div>`}<div class="ntc-smallbtns">${button(f.flipped?'↶ 返回正面':'查看释义与例句 ↻','flip')}</div></div><div class="ntc-actions">${button('← 上一张','flash-prev','',f.at===0)}${f.at===f.ids.length-1?button('综合练习 →','quiz-page','ntc-primary'):button('下一张 →','flash-next','ntc-primary')}</div><div class="ntc-footnote">先看正面回忆词义；需要时翻到背面查看拼音、释义与例句。无需翻面即可切换卡片。</div></div>`}
const contextAlternatives={"0": [13, 21, 28], "1": [13, 21, 28], "2": [13, 21, 28], "3": [13, 21, 28], "4": [13, 21, 28], "5": [8, 11, 12], "6": [13, 21, 28], "7": [13, 21, 28], "8": [13, 21, 28], "9": [13, 21, 28], "10": [13, 21, 28], "11": [13, 21, 28], "12": [13, 21, 28], "13": [13, 21, 28], "14": [8, 11, 12], "15": [13, 21, 28], "16": [13, 21, 28], "17": [8, 11, 12], "18": [13, 21, 28], "19": [13, 21, 28], "20": [13, 15, 16], "21": [13, 21, 28], "22": [13, 21, 28], "23": [13, 21, 28], "24": [13, 21, 28], "25": [13, 21, 28], "26": [13, 21, 28], "27": [13, 21, 28], "28": [13, 21, 28], "29": [13, 21, 28], "30": [13, 21, 28], "31": [13, 21, 28], "32": [8, 11, 12], "33": [13, 21, 28]};
const CONFUSABLE={3:[7,32],7:[3,32],32:[3,7]};
function makeQuestions(ids){let types=ids.map(id=>id%3===2?'context':id%3===0?'listen':'meaning');let positions=shuffle(ids.map((_,i)=>i%4));return shuffle(ids.map((id,i)=>{let alternatives=types[i]==='context'?contextAlternatives[id]:null;let opts=alternatives?shuffle(alternatives):shuffle(WORDS.filter(d=>d.id!==id&&!(CONFUSABLE[id]||[]).includes(d.id)).map(d=>d.id)).slice(0,3);opts.splice(positions[i],0,id);return {id,type:types[i],opts,correct:positions[i],picked:null}}))}
function startQuiz(redraw=true,ids=null){student.quiz={questions:makeQuestions(ids||WORDS.map(d=>d.id)),at:0,done:false,recorded:false};save();if(redraw)render()}
function quizView(){let q=student.quiz;if(q.done)return quizResults();let x=q.questions[q.at],d=WORDS[x.id],answered=x.picked!==null;return `<div class="ntc-panel">${heading('综合练习','听音选词 · 根据越南语释义选词 · 选词填空',`${q.at+1}/${q.questions.length}题`)}${meter(q.at,q.questions.length)}<div class="ntc-label">${x.type==='listen'?'听一听 · 听音选词':x.type==='meaning'?'认一认 · 根据越南语释义选词':'用一用 · 选词填空'}</div>${x.type==='listen'?`<button data-audio-word="${d.id}" class="ntc-primary">◖ 听词语</button><div class="ntc-footnote">如设备没有中文语音，可切换为根据越南语释义选词。</div>${button('切换为释义题','quiz-as-meaning','',answered)}`:x.type==='meaning'?`<div class="ntc-note">请根据越南语释义选择正确的汉语词语： <strong>${escapeHTML(d.m)}</strong></div>`:`<div class="ntc-cn">${escapeHTML(d.s.replace(d.w,'____'))}</div>`}<div class="ntc-quizopts">${x.opts.map((id,i)=>`<button data-answer="${i}" ${answered?'disabled':''} class="${answered?(i===x.correct?'ntc-correct':i===x.picked?'ntc-wrong':''):''}">${'ABCD'[i]}. ${WORDS[id].w}</button>`).join('')}</div>${answered?`<div class="ntc-note" role="status"><strong>${x.picked===x.correct?'✓ 正确':'✕ 不正确'}</strong><div class="ntc-cn">${d.w} · ${escapeHTML(d.p)}</div>${escapeHTML(d.m)}<br>${escapeHTML(d.s)}</div><div class="ntc-actions"><button data-audio-example="${d.id}">◖ 听例句</button>${button(q.at===q.questions.length-1?'查看结果 →':'下一题 →','quiz-next','ntc-primary')}</div>`:''}</div>`}
function pickQuiz(i){let q=student.quiz,x=q.questions[q.at];if(x.picked!==null)return;x.picked=i;if(i!==x.correct)student.memory[x.id]='review';save();render()}
function nextQuiz(){let q=student.quiz;if(q.questions[q.at].picked===null)return;if(q.at<q.questions.length-1)q.at++;else{q.done=true;if(!q.recorded){student.quizHistory.push({date:new Date().toISOString(),answers:q.questions.map(x=>({id:x.id,ok:x.picked===x.correct})),total:q.questions.length});q.recorded=true}}save();render()}
function quizResults(){let q=student.quiz,wrong=q.questions.filter(x=>x.picked!==x.correct),correct=q.questions.length-wrong.length;return `<div class="ntc-panel">${heading('综合练习结果','正确答案与待复习词语')}<div class="ntc-score">${correct}<small> / ${q.questions.length}题答对</small></div><div class="ntc-tag">${wrong.length}题答错</div>${wrong.map(x=>`<div class="ntc-miniresult"><strong>${WORDS[x.id].w}</strong> · ${escapeHTML(WORDS[x.id].p)}<br>你的选择： ${WORDS[x.opts[x.picked]].w}<br>正确释义： ${escapeHTML(WORDS[x.id].m)}<br>${escapeHTML(WORDS[x.id].s)}</div>`).join('')}<div class="ntc-actions">${button('重新练习全课词语','quiz-restart')}${button('重练错词','quiz-retry','',!wrong.length)}${button('连词成句 →','order-page','ntc-primary')}</div></div>`}
function startOrder(ids=null,redraw=true){let chosen=ids||WORDS.map(d=>d.id);student.order={ids:shuffle(chosen),at:0,bank:[],selected:[],checked:false,answers:[],done:false,recorded:false};newOrderQuestion();save();if(redraw)render()}
function newOrderQuestion(){let o=student.order;o.bank=shuffle(CHUNKS[o.ids[o.at]].map((_,i)=>i));if(o.bank.every((x,i)=>x===i))o.bank.reverse();o.selected=[];o.checked=false}
function orderView(){let o=student.order;if(o.done)return orderResults();let id=o.ids[o.at],d=WORDS[id],chunks=CHUNKS[id],ok=o.selected.every((x,i)=>x===i);return `<div class="ntc-panel">${heading('连词成句 · 全课复习','使用已学的40个例句，题目随机排列',`${o.at+1}/${o.ids.length}题`)}${meter(o.at,o.ids.length)}<div class="ntc-label">重点词语 · ${d.w}</div><p class="ntc-caption">按顺序选择词语，点击已选词语可将其放回。</p><div class="ntc-orderanswer ${o.checked?(ok?'ntc-correct':'ntc-wrong'):''}" aria-label="已排列的句子">${o.selected.length?o.selected.map((index,i)=>`<button data-remove="${i}" ${o.checked?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join(''):'<span class="ntc-caption">请在这里排列句子……</span>'}</div><div class="ntc-chunks" aria-label="待选词语">${o.bank.map(index=>`<button class="${o.selected.includes(index)?'used':''}" data-chunk="${index}" ${o.checked||o.selected.includes(index)?'disabled':''}>${escapeHTML(chunks[index])}</button>`).join('')}</div><div class="ntc-actions"><div class="ntc-smallbtns">${button('↶ 撤销最后一项','order-undo','',!o.selected.length||o.checked)}${button('重新排列','order-clear','',!o.selected.length||o.checked)}</div>${button('检查答案','order-check','ntc-primary',o.selected.length!==chunks.length||o.checked)}</div>${o.checked?`<div class="ntc-note" role="status"><strong>${ok?'✓ 与例句顺序一致':'✕ 与例句顺序不一致'}</strong><div class="ntc-label">原例句</div><div class="ntc-cn">${escapeHTML(d.s)}</div><button data-audio-example="${id}">◖ 听例句</button></div><div class="ntc-actions"><span></span>${button(o.at===o.ids.length-1?'查看结果 →':'下一题 →','order-next','ntc-primary')}</div>`:''}<div class="ntc-footnote">本练习按原例句顺序评分，其他语序也可能符合语法。</div></div>`}
function addChunk(index){let o=student.order;if(o.checked||o.selected.includes(index))return;o.selected.push(index);save();render()}
function removeChunk(index){let o=student.order;if(o.checked)return;o.selected.splice(index,1);save();render()}
function checkOrder(){let o=student.order;if(o.checked||o.selected.length!==CHUNKS[o.ids[o.at]].length)return;o.checked=true;let id=o.ids[o.at],ok=o.selected.every((x,i)=>x===i);o.answers.push({id,ok});if(!ok)student.memory[id]='review';save();render()}
function nextOrder(){let o=student.order;if(!o.checked)return;if(o.at<o.ids.length-1){o.at++;newOrderQuestion()}else{o.done=true;if(!o.recorded){student.orderHistory.push({date:new Date().toISOString(),answers:o.answers.map(x=>({...x})),total:o.ids.length});o.recorded=true}}save();render()}
function orderResults(){let o=student.order,wrong=o.answers.filter(x=>!x.ok).map(x=>x.id),correct=o.answers.length-wrong.length;return `<div class="ntc-panel">${heading('连词成句结果','第22课综合复习')}<div class="ntc-score">${correct}<small> / ${o.answers.length}题答对</small></div><div class="ntc-tag">${wrong.length} 题需要重新练习</div>${wrong.map(id=>`<div class="ntc-miniresult"><strong>${WORDS[id].w}</strong><br><span class="ntc-cn">${escapeHTML(WORDS[id].s)}</span></div>`).join('')}<div class="ntc-actions">${button('重新练习全课句子','order-restart')}${button('重练错题','order-retry','',!wrong.length)}${button('查看学习统计 →','stats-page','ntc-primary')}</div></div>`}
function activityScore(kind,g){let history=kind==='quiz'?student.quizHistory:student.orderHistory,record=history[history.length-1],answers=record?.answers||[],ids=group(g).map(d=>d.id),inGroup=answers.filter(x=>ids.includes(x.id));let active=kind==='quiz'?student.quiz:student.order;if(active&&!active.done){let partial=kind==='quiz'?active.questions.filter(x=>x.picked!==null).map(x=>({id:x.id,ok:x.picked===x.correct})):active.answers;inGroup=partial.filter(x=>ids.includes(x.id));if(inGroup.length)return inGroup.filter(x=>x.ok).length+'/'+inGroup.length+' 进行中'}return inGroup.length?inGroup.filter(x=>x.ok).length+'/'+inGroup.length:'尚未练习'}
function statsView(){let weak=weakIds();return `<div class="ntc-panel">${heading('学习统计','当前浏览器中的第22课学习进度','第22课 · 34个词语')}<div class="ntc-statrow"><div class="ntc-stat"><label>已学词语</label><strong>${totalLearned()}<small> / 34</small></strong></div><div class="ntc-stat"><label>需要复习</label><strong>${weak.length}<small>个词语</small></strong></div></div><div class="ntc-tablewrap"><table class="ntc-table"><thead><tr><th>组别</th><th>已学习</th><th>待复习</th><th>综合练习</th><th>连词成句</th></tr></thead><tbody>${[0,1,2].map(g=>`<tr><td>组别 ${g+1}<div class="ntc-caption">${group(g).length}个词语</div></td><td>${learned(g)}/${group(g).length}</td><td>${group(g).filter(d=>memory(d.id)==='review').length}</td><td>${activityScore('quiz',g)}</td><td>${activityScore('order',g)}</td></tr>`).join('')}</tbody></table></div><div class="ntc-footnote">按词语所属组显示答对题数／已答题数。优先显示本轮进度，否则显示最近一轮结果。</div><hr><div class="ntc-sectionhead"><h2>待复习词语</h2>${button('用词汇卡片复习 →','flash-weak','',!weak.length||!allLearned())}</div><div class="ntc-terms">${weak.length?weak.map(id=>`<button data-word="${id}">${WORDS[id].w}</button>`).join(''):'<span class="ntc-caption">暂无需要复习的错词。</span>'}</div><div class="ntc-note">继续学习：组别 ${student.bookmark.g+1} · 词语 ${student.bookmark.idx+1}/${group(student.bookmark.g).length}.<br>本页累计学习时间约 ${Math.floor(student.timeMs/60000)} 分钟。已完成综合练习轮数： ${student.quizHistory.length}; 连词成句轮数： ${student.orderHistory.length}.</div><div class="ntc-actions">${button('继续学习','resume','ntc-primary')}${button('导出学习记录','backup')}${button('恢复学习记录','restore')}</div><div class="ntc-footnote">答错词语会列入待复习词语。浏览词汇卡片不等于掌握词语。</div></div>`}
function render(){clearWriting();let total=totalLearned();$('ntc-profile-button').textContent='HSK5 · 第22课';$('ntc-bookmark').textContent=student?total+'/34 个已学词语':'';$('ntc-tabs').innerHTML=pages.map((name,i)=>`<button class="ntc-tab ${ui.page===i?'active':''}" data-page="${i}" aria-pressed="${ui.page===i}">${i<5?i+1+'. ':''}${name}${i>=2&&i<=4&&!allLearned()?' 🔒':''}</button>`).join('');let showGroups=ui.page===1;$('ntc-groups').hidden=!showGroups;$('ntc-groups').innerHTML=showGroups?[0,1,2].map(g=>`<button data-group="${g}" class="${g===ui.g?'active':''}">组别 ${g+1} · ${group(g).length}个词语 · ${learned(g)}/${group(g).length}</button>`).join(''):'';$('ntc-sidegroups').innerHTML=showGroups?'<div class="ntc-navtitle">当前词汇组</div>'+[0,1,2].map(g=>`<button class="ntc-sidegroup ${g===ui.g?'active':''}" data-group="${g}"><span>组别 ${g+1}<br><small>词语 ${g*10+1}–${g*10+group(g).length}</small></span><small>${learned(g)}/${group(g).length}</small></button>`).join(''):'<div class="ntc-navtitle">第22课学习进度</div><div style="padding:0 10px">'+total+'/34 个已学词语'+meter(total,34)+'</div>';$('ntc-sidefoot').innerHTML='学完生词 →<br>全课综合复习。<br><br>进度保存在<br>当前浏览器中。';let html;if(ui.page>=2&&ui.page<=4&&!allLearned())html=gate();else html=[listView,studyView,flashView,quizView,orderView,statsView][ui.page]();$('ntc-view').innerHTML=html;if(ui.page===1)setupWriting();}
function stopAudio(){audioGeneration++;if(playback){playback.pause();playback=null}if('speechSynthesis' in window)window.speechSynthesis.cancel()}
const AUDIO_INDEX={"过分":"data:audio/mpeg;base64,","对孩子提出过分的要求，可能会给他们带来压力。":"data:audio/mpeg;base64,","强调":"data:audio/mpeg;base64,","老师反复强调，阅读以后还要认真思考。":"data:audio/mpeg;base64,","作文":"data:audio/mpeg;base64,","写完作文以后，她又仔细修改了一遍。":"data:audio/mpeg;base64,","观点":"data:audio/mpeg;base64,","讨论时，每个人都可以表达自己的观点。":"data:audio/mpeg;base64,","客观":"data:audio/mpeg;base64,","评价一部作品时，我们应该尽量保持客观。":"data:audio/mpeg;base64,","全面":"data:audio/mpeg;base64,","作决定之前，需要先全面了解情况。":"data:audio/mpeg;base64,","转变":"data:audio/mpeg;base64,","参加这次活动以后，他开始转变自己的学习方式。":"data:audio/mpeg;base64,","观念":"data:audio/mpeg;base64,","随着社会的发展，人们的观念也在不断变化。":"data:audio/mpeg;base64,","火柴":"data:audio/mpeg;base64,","他划了一根火柴，点亮了桌上的蜡烛。":"data:audio/mpeg;base64,","灰":"data:audio/mpeg;base64,","大火过后，那些旧报纸都变成了灰。":"data:audio/mpeg;base64,","一旦":"data:audio/mpeg;base64,","一旦发现问题，就应该及时解决。":"data:audio/mpeg;base64,","王宫":"data:audio/mpeg;base64,","游客们正在参观一座古老的王宫。":"data:audio/mpeg;base64,","王子":"data:audio/mpeg;base64,","这个童话讲的是一位勇敢的王子的故事。":"data:audio/mpeg;base64,","属于":"data:audio/mpeg;base64,","这间活动室属于大家，请共同保持整洁。":"data:audio/mpeg;base64,","对待":"data:audio/mpeg;base64,","不管任务大小，我们都应该认真对待。":"data:audio/mpeg;base64,","交换":"data:audio/mpeg;base64,","讨论结束后，两位老师交换了意见。":"data:audio/mpeg;base64,","拥有":"data:audio/mpeg;base64,","她拥有丰富的教学经验，很受学生欢迎。":"data:audio/mpeg;base64,","巨大":"data:audio/mpeg;base64,","网络的发展给人们的生活带来了巨大变化。":"data:audio/mpeg;base64,","承认":"data:audio/mpeg;base64,","他主动承认了错误，并向大家道歉。":"data:audio/mpeg;base64,","人性":"data:audio/mpeg;base64,","这部小说通过人物的选择，表现了人性的复杂。":"data:audio/mpeg;base64,","完美":"data:audio/mpeg;base64,","这个方案虽然还不完美，但已经有了很大进步。":"data:audio/mpeg;base64,","难免":"data:audio/mpeg;base64,","刚开始学习时，难免会遇到困难，不要轻易放弃。":"data:audio/mpeg;base64,","疼爱":"data:audio/mpeg;base64,","爷爷奶奶一直十分疼爱她。":"data:audio/mpeg;base64,","平等":"data:audio/mpeg;base64,","每个人都应该拥有平等的学习机会。":"data:audio/mpeg;base64,","自私":"data:audio/mpeg;base64,","只考虑自己而不顾别人，是一种自私的行为。":"data:audio/mpeg;base64,","倾向":"data:audio/mpeg;base64,","比较了两个方案以后，我更倾向于选择第二个。":"data:audio/mpeg;base64,","理由":"data:audio/mpeg;base64,","提出不同意见时，请说明你的理由。":"data:audio/mpeg;base64,","道德":"data:audio/mpeg;base64,","学校不仅要传授知识，还要重视道德教育。":"data:audio/mpeg;base64,","自从":"data:audio/mpeg;base64,","自从参加读书会以后，她认识了不少新朋友。":"data:audio/mpeg;base64,","童话":"data:audio/mpeg;base64,","每天睡觉前，妈妈都会给孩子读一个童话。":"data:audio/mpeg;base64,","价值":"data:audio/mpeg;base64,","这批资料具有很高的研究价值。":"data:audio/mpeg;base64,","单纯":"data:audio/mpeg;base64,","学习时，不能单纯依靠记忆，还要学会理解。":"data:audio/mpeg;base64,","主张":"data:audio/mpeg;base64,","他主张先调查，再提出解决问题的方案。":"data:audio/mpeg;base64,","知感":"data:audio/mpeg;base64,","学习不能只停留在知感层面，还需要深入思考。":"data:audio/mpeg;base64,"};
function speak(text){stopAudio();const path=AUDIO_INDEX[text];if(!path){toast('未找到此内容的配套音频。');return}const generation=audioGeneration;const player=new Audio(path);playback=player;player.playbackRate=speed;player.onerror=()=>{if(generation===audioGeneration){$('ntc-voice-label').textContent='音频未加载';toast('无法加载音频，请确认 HTML 与 audio 文件夹一起保存或上传。')}};player.onended=()=>{if(playback===player)playback=null};player.play().then(()=>{if(generation!==audioGeneration){player.pause();return}$('ntc-voice-label').textContent='朗读：Xiaoxiao · 固定 MP3';}).catch(()=>{if(generation===audioGeneration)toast('音频暂时无法播放，请确认音频文件存在后再次点击。')})}
function backup(){const content=JSON.stringify({format:'ntc-hsk5-bai22-v3',profile:student},null,2);let url=URL.createObjectURL(new Blob([content],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='HSK5_Bai22_TienDo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function restore(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{let v=JSON.parse(await input.files[0].text()),p=v.profile;if(v.format!=='ntc-hsk5-bai22-v3'||!p||typeof p.name!=='string'||typeof p.clas!=='string'||!Array.isArray(p.studied)||p.studied.some(id=>!Number.isInteger(id)||id<0||id>=34)||!p.memory)throw Error();if(!confirm('恢复第22课学习记录？当前记录将被替换。'))return;let id=store.active||'local';let clean=createStudent(p.name,p.clas);clean.studied=[...new Set(p.studied)];for(let k=0;k<34;k++)if(['remembered','review'].includes(p.memory[k]))clean.memory[k]=p.memory[k];if(p.bookmark&&Number.isInteger(p.bookmark.g)&&p.bookmark.g>=0&&p.bookmark.g<3&&Number.isInteger(p.bookmark.idx)&&p.bookmark.idx>=0&&p.bookmark.idx<group(p.bookmark.g).length)clean.bookmark=p.bookmark;for(let key of ['quizHistory','orderHistory'])if(Array.isArray(p[key]))clean[key]=p[key].filter(r=>r&&Array.isArray(r.answers)&&r.answers.every(a=>Number.isInteger(a.id)&&a.id>=0&&a.id<34&&typeof a.ok==='boolean'));clean.timeMs=Math.max(0,Number(p.timeMs)||0);store.profiles[id]=clean;store.active=id;student=clean;ui={page:5,g:0,idx:0,pinyin:false};save();render();toast('已恢复已学词语、复习状态与练习记录。')}catch(e){toast('无法读取有效的HSK5第22课学习记录。')}});input.click()}
root.addEventListener('click',event=>{let b=event.target.closest('button');if(!b||b.disabled)return;const data=b.dataset;if(data.audioWord!==undefined){speak(WORDS[+data.audioWord].w);return}if(data.audioExample!==undefined){speak(WORDS[+data.audioExample].s);return}if(data.page!==undefined){go(+data.page);return}if(data.group!==undefined){chooseGroup(+data.group);return}if(data.word!==undefined){let id=+data.word;ui.g=groupOf(id);ui.idx=id-ui.g*10;go(1);return}if(data.answer!==undefined){stopAudio();pickQuiz(+data.answer);return}if(data.chunk!==undefined){addChunk(+data.chunk);return}if(data.remove!==undefined){removeChunk(+data.remove);return}let a=data.action;if(!a)return;if(a==='stop'){stopAudio();return}switch(a){case'strokes':animateWriting();return;case'resume':ui.g=student.bookmark.g;ui.idx=student.bookmark.idx;go(1);return;case'pinyin':ui.pinyin=!ui.pinyin;break;case'prev-study':{let id=currentWord().id-1;ui.g=groupOf(id);ui.idx=id-ui.g*10;break}case'mark-study':stopAudio();markStudy();return;case'flip':student.flash.flipped=!student.flash.flipped;break;case'flash-all':if(!allLearned()){go(2);return}ui.page=2;startFlash('all');return;case'flash-weak':if(!allLearned()){go(2);return}ui.page=2;startFlash('weak');return;case'flash-prev':student.flash.at--;student.flash.flipped=false;break;case'flash-next':student.flash.at++;student.flash.flipped=false;break;case'quiz-page':go(3);return;case'order-page':go(4);return;case'stats-page':go(5);return;case'quiz-as-meaning':student.quiz.questions[student.quiz.at].type='meaning';break;case'quiz-next':stopAudio();nextQuiz();return;case'quiz-restart':startQuiz();return;case'quiz-retry':startQuiz(true,student.quiz.questions.filter(x=>x.picked!==x.correct).map(x=>x.id));return;case'order-undo':removeChunk(student.order.selected.length-1);return;case'order-clear':student.order.selected=[];break;case'order-check':checkOrder();return;case'order-next':stopAudio();nextOrder();return;case'order-restart':startOrder();return;case'order-retry':startOrder(student.order.answers.filter(x=>!x.ok).map(x=>x.id));return;case'backup':backup();return;case'restore':restore();return;default:return}save();render()});
root.addEventListener('change',event=>{if(event.target.id==='ntc-rate')speed=Number(event.target.value)});


let strokeWriters=[],strokeRun=0;
function clearWriting(){strokeRun++;for(const w of strokeWriters){w.pauseAnimation();}strokeWriters=[];}
function setupWriting(){const box=$('ntc-writing');if(!box)return;box.innerHTML='';for(const c of currentWord().w){const el=document.createElement('span');el.setAttribute('aria-label',c);box.appendChild(el);if(!STROKE_DATA[c]||typeof HanziWriter==='undefined'){el.textContent=c;if(!/[\u4e00-\u9fff]/.test(c)){el.style.width='24px';el.style.fontSize='30px';}continue;}strokeWriters.push(HanziWriter.create(el,c,{width:92,height:106,padding:3,strokeColor:'#a3455d',radicalColor:'#a3455d',outlineColor:'#ecd2db',strokeAnimationSpeed:0.7,delayBetweenStrokes:180,charDataLoader:()=>STROKE_DATA[c]}));}}
async function animateWriting(){const token=++strokeRun,list=[...strokeWriters];if(!list.length){toast('暂时无法显示笔顺。');return;}const button=root.querySelector('[data-action="strokes"]');if(button)button.disabled=true;try{for(const w of list)await w.hideCharacter({duration:0});for(const w of list){if(token!==strokeRun)return;await w.animateCharacter();}}finally{if(token===strokeRun&&button)button.disabled=false;}}

let lastTick=Date.now();setInterval(()=>{let now=Date.now();if(student&&!document.hidden){student.timeMs+=Math.min(now-lastTick,15000);save()}lastTick=now},15000);
window.addEventListener('pagehide',()=>{save();stopAudio()});
if(student&&ui.page>=2&&ui.page<=4&&allLearned()){if(ui.page===2&&!student.flash)startFlash('all',false);if(ui.page===3&&!student.quiz)startQuiz(false);if(ui.page===4&&!student.order)startOrder(null,false)}
save();render();if(!storageOK)toast('浏览器阻止保存数据，建议导出学习记录作为备份。');

